#include <stdlib.h>

#define ARRAY_SIZE 256

int main(int argc, char *argv[]) {
    char array[ARRAY_SIZE];
    char abort_flag = 0;

    // allocate a temporary buffer
    char *tmp = (char *)malloc(sizeof(char) * ARRAY_SIZE);
    if (tmp == NULL) {
        printf("Error allocating memory\n");
        exit(1);
    }

    // store characters from stdin in tmp until receiving a newline
    int i = 0;
    while (1) {
        tmp[i] = getchar();
        if (tmp[i] == '\n') {
            break;
        }
        i++;
    }
    tmp[i] = '\0';

    // if we received no characters, free the memory and set abort flag
    if (i == 0) {
        free(tmp);
        abort_flag = 1;
    }

    // if we received characters, store them in the array
    else {
        for (i = 0; i < ARRAY_SIZE; i++) {
            array[i] = tmp[i];
        }
    }

    // tidy up
	free(tmp);

    // if we received no characters, print a message and exit
    if (abort_flag) {
        printf("No characters received\n");
        exit(1);
    }

    // if we received characters, print them
    else {
        printf("Received characters: ");
        for (i = 0; i < ARRAY_SIZE; i++) {
            printf("%c", array[i]);
        }
        printf("\n");
    }

    return 0;
}

